import type { CollectionEntry } from "astro:content";

export interface TimelineSceneNode {
  id: string;
  label: string;
  subtitle?: string;
  q: number;
  r: number;
  variant: string;
  size: string;
  active?: boolean;
  selected?: boolean;
}

export interface TimelineSceneEdge {
  from: string;
  to: string;
  kind: string;
  active: boolean;
  muted: boolean;
}

export interface TimelineSceneRecord {
  id: string;
  eyebrow: string;
  title: string;
  subtitle: string;
  overview: string;
  summary: string;
  displayPeriod: string;
  period: string;
  organization: string;
  mode: string;
  scale: string;
}

type PagesEntry = CollectionEntry<"pages">;

interface TimelineItemInput {
  id: string;
  title: string;
  organization: string;
  period: string;
  fullPeriod?: string;
  displayPeriod?: string;
  overview?: string;
  summary?: string;
  scale?: string;
}

interface TimelineSceneTopologyInput {
  entry: PagesEntry;
  mode: string;
  scale: string;
  items: TimelineItemInput[];
}

function normalizePeriod(period: string) {
  return period.split("-")[0]?.trim() || period;
}

export function createTimelineSceneTopology({
  entry,
  mode,
  scale,
  items,
}: TimelineSceneTopologyInput) {
  const timelineAnchorNodes = items.map((item, index) => ({
    id: `${item.id}-start-time`,
    label: item.period,
    subtitle: "Start Time",
    q: -10 + index * 2,
    r: 0,
    variant: "anchor",
    size: "sm",
  }));

  const timelineEventNodes = timelineAnchorNodes.map((anchor, index) => ({
    id: items[index].id,
    label: items[index].title,
    subtitle: items[index].organization,
    q: anchor.q + (index % 2 === 0 ? 0 : 3),
    r: anchor.r + (index % 2 === 0 ? 3 : -3),
    variant: "node",
    size: index === 0 ? "lg" : "md",
  }));

  const timelineNodes: TimelineSceneNode[] = [
    {
      id: entry.data.id,
      label: "Timeline",
      subtitle: entry.data.subtitle ?? "Career chronology",
      q: -14,
      r: 0,
      variant: "root",
      size: "root",
      active: true,
      selected: true,
    },
    ...timelineAnchorNodes,
    ...timelineEventNodes,
  ];

  const timelineEdges: TimelineSceneEdge[] = [
    {
      from: entry.data.id,
      to: timelineAnchorNodes[0]?.id ?? entry.data.id,
      kind: "parent",
      active: true,
      muted: false,
    },
    ...timelineAnchorNodes.flatMap((anchor, index) => {
      const nextAnchor = timelineAnchorNodes[index + 1];
      const child = timelineEventNodes[index];
      const edges: TimelineSceneEdge[] = [];

      if (nextAnchor) {
        edges.push({
          from: anchor.id,
          to: nextAnchor.id,
          kind: "parent",
          active: index === 0,
          muted: index !== 0,
        });
      }

      if (child) {
        edges.push({
          from: anchor.id,
          to: child.id,
          kind: "parent",
          active: index === 0,
          muted: index !== 0,
        });
      }

      return edges;
    }),
  ];

  const timelineRecords: TimelineSceneRecord[] = [
    {
      id: entry.data.id,
      eyebrow: entry.data.eyebrow ?? "Timeline",
      title: entry.data.title,
      subtitle: entry.data.subtitle ?? "Career chronology",
      overview: entry.data.summary,
      summary: entry.data.summary,
      displayPeriod: items[0]?.displayPeriod ?? items[0]?.fullPeriod ?? items[0]?.period ?? "2008",
      period: items[0]?.period ?? "2008",
      organization: "Across infrastructure, operations, and service management",
      mode,
      scale,
    },
    ...items.map((item) => ({
      id: item.id,
      eyebrow: "Timeline Chapter",
      title: item.title,
      subtitle: item.organization,
      overview: item.overview || item.summary || `${item.title} at ${item.organization}`,
      summary: item.summary || `${item.title} at ${item.organization}`,
      displayPeriod: item.displayPeriod || item.fullPeriod || item.period,
      period: item.period,
      organization: item.organization,
      mode,
      scale: item.scale || scale,
    })),
  ];

  return {
    timelineNodes,
    timelineEdges,
    timelineRecords,
    selectedId: entry.data.id,
    rootNode: timelineNodes[0],
    anchorNodes: timelineAnchorNodes,
    eventNodes: timelineEventNodes,
    items,
    normalizePeriod,
  };
}
